SELECT symbol, delivery_status, outcome_reason, COUNT(*) AS n, MIN(observed_at) AS first_obs, MAX(observed_at) AS last_obs FROM crypto_ai.market_price_event WHERE observed_at BETWEEN '2026-10-11 22:43:20' AND '2026-10-11 22:43:40' GROUP BY symbol, delivery_status, outcome_reason ORDER BY symbol LIMIT 100;
SELECT id, observed_at, UNIX_TIMESTAMP(observed_at) AS epoch_s, price, source, created_at, delivery_status, ordering_slot, outcome_reason FROM crypto_ai.market_price_event WHERE symbol = 'EGLDUSDT' AND observed_at BETWEEN '2026-10-11 22:39:20' AND '2026-10-11 22:40:10' ORDER BY observed_at LIMIT 100;